    ctx.moveTo(-12, -46); ctx.lineTo(4, -42); ctx.lineTo(16, -50);
    ctx.stroke();
    // molten cracks
    ctx.strokeStyle = glow;
    ctx.lineWidth = 1.4;
    ctx.shadowColor = glow;
