    ctx.moveTo(-8, -70); ctx.lineTo(-2, -60); ctx.lineTo(-7, -52); ctx.lineTo(1, -44);
    ctx.moveTo(9, -73); ctx.lineTo(6, -62); ctx.lineTo(12, -56);
    ctx.stroke();
    ctx.shadowBlur = 0;
    // head
    ctx.fillStyle = mixHex(rock, '#000', 0.2);
    ctx.beginPath();
    ctx.moveTo(-10, -79); ctx.lineTo(-8, -91); ctx.lineTo(8, -92); ctx.lineTo(12, -80);
    ctx.closePath(); ctx.fill();
    // eyes
    ctx.fillStyle = glow;
    ctx.shadowColor = glow;
    ctx.shadowBlur = 10;
    ctx.beginPath(); ctx.arc(-6, -85, 2, 0, TAU); ctx.fill();
    ctx.beginPath(); ctx.arc(4, -85, 2, 0, TAU); ctx.fill();
    ctx.shadowBlur = 0;
    // shoulder rocks
    ctx.fillStyle = mixHex(rock, '#fff', 0.06);
    ctx.beginPath(); ctx.arc(-20, -72, 10, 0, TAU); ctx.fill();
    ctx.beginPath(); ctx.arc(20, -72, 9, 0, TAU); ctx.fill();
  }

  drawBruteEnemy(ctx, t, flash, atk, zone, boss) {
    const flesh = mixHex('#2a2118', zone.enemy, 0.5 + flash * 0.35);
    const glow = zone.accent;
    const bob = Math.sin(t * 1.9) * 2;
    const stomp = atk < 1 ? Math.sin(Math.PI * atk) : 0;
    // legs
    ctx.strokeStyle = mixHex(flesh, '#000', 0.2);
    ctx.lineWidth = 14;
    ctx.lineCap = 'round';
    ctx.beginPath(); ctx.moveTo(-8, -34); ctx.lineTo(-18, -14); ctx.lineTo(-20, -2); ctx.stroke();
    ctx.beginPath(); ctx.moveTo(10, -34); ctx.lineTo(20, -16 + stomp * 2); ctx.lineTo(25, -2); ctx.stroke();
    // torso
    ctx.fillStyle = flesh;
    ctx.beginPath();
    ctx.ellipse(2, -58 + bob, 30, 30, 0, 0, TAU);
    ctx.fill();
    // hunch
    ctx.beginPath();
    ctx.ellipse(-2, -78 + bob, 24, 16, -0.2, 0, TAU);
    ctx.fill();
    // arms
    for (const side of [-1, 1]) {
      const swingA = side === -1 && atk < 1 ? -0.3 - Math.sin(Math.PI * atk) * 1.2 : 0.1;
      ctx.save();
      ctx.translate(side * 28, -64 + bob);
      ctx.rotate(swingA);
      ctx.fillStyle = mixHex(flesh, '#000', 0.12);
      rr(ctx, -5, -2, 14, 48, 7); ctx.fill();
      // claws
      ctx.strokeStyle = '#b9b49c';
      ctx.lineWidth = 1.6;
      for (let i = 0; i < 3; i++) {
        ctx.beginPath(); ctx.moveTo(side * 7, 42); ctx.lineTo(side * 7 + i * 3 - 3, 50); ctx.stroke();
      }
      ctx.restore();
    }
    // head
    ctx.fillStyle = mixHex(flesh, '#000', 0.15);
    ctx.beginPath(); ctx.ellipse(-10, -84 + bob, 13, 11, -0.2, 0, TAU); ctx.fill();
    // jaw
    ctx.fillStyle = '#33271d';
    ctx.beginPath(); ctx.ellipse(-19, -78 + bob, 7, 5, 0.2, 0, TAU); ctx.fill();
    // teeth
    ctx.fillStyle = '#c5bea3';
    for (let i = 0; i < 3; i++) {
      ctx.beginPath();
      ctx.moveTo(-24 + i * 3, -80 + bob); ctx.lineTo(-23 + i * 3, -76 + bob); ctx.lineTo(-21 + i * 3, -80 + bob);
      ctx.closePath(); ctx.fill();
    }
    // glowing veins
    ctx.strokeStyle = glow;
    ctx.lineWidth = 1.6;
    ctx.shadowColor = glow;
    ctx.shadowBlur = 8;
    ctx.beginPath();
    ctx.moveTo(-10, -70 + bob); ctx.lineTo(-2, -60 + bob); ctx.lineTo(-8, -48 + bob);
    ctx.moveTo(10, -72 + bob); ctx.lineTo(6, -58 + bob); ctx.lineTo(12, -46 + bob);
    ctx.stroke();
    ctx.shadowBlur = 0;
    // eyes
    ctx.fillStyle = glow;
    ctx.shadowColor = glow;
    ctx.shadowBlur = 9;
    ctx.beginPath(); ctx.arc(-16, -88 + bob, 1.8, 0, TAU); ctx.fill();
    ctx.beginPath(); ctx.arc(-7, -89 + bob, 1.6, 0, TAU); ctx.fill();
    ctx.shadowBlur = 0;
    // horns
    ctx.fillStyle = '#5b5242';
    ctx.beginPath(); ctx.moveTo(-18, -92 + bob); ctx.lineTo(-24, -104 + bob); ctx.lineTo(-11, -94 + bob); ctx.closePath(); ctx.fill();
    ctx.beginPath(); ctx.moveTo(-2, -93 + bob); ctx.lineTo(4, -104 + bob); ctx.lineTo(5, -90 + bob); ctx.closePath(); ctx.fill();
  }

  drawSentryEnemy(ctx, t, flash, atk, zone, boss) {
    const metal = mixHex('#231f19', zone.enemy, 0.45 + flash * 0.4);
    const glow = zone.accent;
    const hover = Math.sin(t * 2.2) * 5;
    const tilt = atk < 1 ? -0.25 * Math.sin(Math.PI * atk) : 0;
    // thruster glow
    const tg = ctx.createRadialGradient(0, 4, 1, 0, 4, 26);
    tg.addColorStop(0, rgba(glow, 0.35));
    tg.addColorStop(1, 'rgba(0,0,0,0)');
    ctx.fillStyle = tg;
    ctx.fillRect(-30, -14, 60, 40);
    // cables
    ctx.strokeStyle = '#17140f';
    ctx.lineWidth = 2;
    for (let i = 0; i < 4; i++) {
      ctx.beginPath();
      ctx.moveTo(-12 + i * 8, -18 + hover);
      ctx.quadraticCurveTo(-14 + i * 8 + Math.sin(t * 2 + i) * 3, 0, -18 + i * 8, 8);
      ctx.stroke();
    }
    ctx.save();
    ctx.translate(0, -46 + hover);
    ctx.rotate(tilt);
    // body
    ctx.fillStyle = metal;
    ctx.beginPath();
    ctx.moveTo(-24, -20); ctx.lineTo(-16, -32); ctx.lineTo(18, -30); ctx.lineTo(26, -14);
    ctx.lineTo(18, 4); ctx.lineTo(-18, 4); ctx.lineTo(-27, -12);
    ctx.closePath();
    ctx.fill();
    ctx.strokeStyle = 'rgba(255,255,255,0.08)';
    ctx.lineWidth = 1;
    ctx.stroke();
    // wing fins
    ctx.fillStyle = mixHex(metal, glow, 0.12);
    ctx.beginPath(); ctx.moveTo(-24, -18); ctx.lineTo(-38, -6); ctx.lineTo(-24, -2); ctx.closePath(); ctx.fill();
    ctx.beginPath(); ctx.moveTo(24, -18); ctx.lineTo(38, -6); ctx.lineTo(24, -2); ctx.closePath(); ctx.fill();
    // eye housing
    ctx.fillStyle = '#0c0b09';
    ctx.beginPath(); ctx.ellipse(-4, -14, 11, 8, 0, 0, TAU); ctx.fill();
    ctx.fillStyle = glow;
    ctx.shadowColor = glow;
    ctx.shadowBlur = 15;
    ctx.beginPath(); ctx.arc(-6, -14, 4.5 + Math.sin(t * 4) * 0.5, 0, TAU); ctx.fill();
    ctx.fillStyle = '#f4ffe0';
    ctx.shadowBlur = 0;
    ctx.beginPath(); ctx.arc(-7, -15, 1.6, 0, TAU); ctx.fill();
    // antenna
    ctx.strokeStyle = '#3f4436';
    ctx.lineWidth = 1.5;
    ctx.beginPath(); ctx.moveTo(10, -30); ctx.lineTo(16, -42); ctx.stroke();
    ctx.fillStyle = '#ff7a2b';
    ctx.beginPath(); ctx.arc(16, -42, 2, 0, TAU); ctx.fill();
    // rivets
    ctx.fillStyle = 'rgba(255,255,255,0.18)';
    for (let i = 0; i < 4; i++) ctx.fillRect(-16 + i * 9, 1, 2, 2);
    ctx.restore();
  }

  drawVoidEnemy(ctx, t, flash, atk, zone, boss) {
    const robe = mixHex('#16101f', zone.enemy, 0.35 + flash * 0.4);
    const glow = zone.accent;
    const float = Math.sin(t * 1.6) * 6;
    const pulse = 0.6 + Math.sin(t * 3) * 0.4;
    // aura
    const ag = ctx.createRadialGradient(0, -54 + float, 2, 0, -54 + float, 58);
    ag.addColorStop(0, rgba(glow, 0.22 * pulse));
    ag.addColorStop(1, 'rgba(0,0,0,0)');
    ctx.fillStyle = ag;
    ctx.fillRect(-70, -120 + float, 140, 130);
    // tendrils
    ctx.strokeStyle = mixHex(robe, glow, 0.15);
    ctx.lineWidth = 3;
    for (let i = 0; i < 5; i++) {
      ctx.beginPath();
      const bx = -20 + i * 10;
      ctx.moveTo(bx, -20 + float);
      ctx.bezierCurveTo(bx + Math.sin(t * 2 + i) * 8, -4, bx + Math.cos(t * 1.7 + i) * 12, 6, bx + Math.sin(t * 2.4 + i) * 6, 14);
      ctx.stroke();
    }
    // robe body
    ctx.fillStyle = robe;
    ctx.beginPath();
    ctx.moveTo(-26, -18 + float);
    ctx.quadraticCurveTo(-34, -56 + float, -16, -82 + float);
    ctx.quadraticCurveTo(0, -98 + float, 16, -82 + float);
    ctx.quadraticCurveTo(34, -56 + float, 26, -18 + float);
    ctx.quadraticCurveTo(0, -4 + float, -26, -18 + float);
    ctx.closePath();
    ctx.fill();
    // tattered hem
    ctx.fillStyle = robe;
    for (let i = 0; i < 5; i++) {
      ctx.beginPath();
      ctx.moveTo(-24 + i * 12, -20 + float);
      ctx.lineTo(-20 + i * 12, -6 + float + (i % 2) * 5);
      ctx.lineTo(-14 + i * 12, -19 + float);
      ctx.closePath(); ctx.fill();
    }
    // inner glow seams
    ctx.strokeStyle = rgba(glow, 0.4 * pulse);
    ctx.lineWidth = 1.2;
    ctx.beginPath();
    ctx.moveTo(0, -82 + float); ctx.lineTo(-6, -54 + float); ctx.lineTo(5, -30 + float);
    ctx.stroke();
    // hood
    ctx.fillStyle = mixHex(robe, '#000', 0.2);
    ctx.beginPath();
    ctx.arc(0, -80 + float, 17, 0, TAU);
    ctx.fill();
    ctx.fillStyle = '#07050a';
    ctx.beginPath();
    ctx.ellipse(-3, -79 + float, 11, 13, 0, 0, TAU);
    ctx.fill();
    // mask / eyes
    ctx.fillStyle = glow;
    ctx.shadowColor = glow;
    ctx.shadowBlur = 12;
    ctx.beginPath(); ctx.ellipse(-6, -82 + float, 2.2, 3.2, 0.2, 0, TAU); ctx.fill();
    ctx.beginPath(); ctx.ellipse(2, -82 + float, 2.2, 3.2, -0.2, 0, TAU); ctx.fill();
    ctx.shadowBlur = 0;
    // arms
    const armA = atk < 1 ? -0.5 - Math.sin(Math.PI * atk) * 0.9 : -0.25;
    for (const side of [-1, 1]) {
      ctx.save();
      ctx.translate(side * 18, -60 + float);
      ctx.rotate(side * (0.35 + armA * 0.3));
      ctx.strokeStyle = robe;
      ctx.lineWidth = 6;
      ctx.beginPath();
      ctx.moveTo(0, 0);
      ctx.quadraticCurveTo(side * 12, 14, side * 8 + Math.sin(t * 2) * 3, 30);
      ctx.stroke();
      // claw
      ctx.strokeStyle = rgba(glow, 0.7);
      ctx.lineWidth = 1.4;
      for (let i = 0; i < 3; i++) {
        ctx.beginPath();
        ctx.moveTo(side * 8, 30);
        ctx.lineTo(side * (6 + i * 3), 38);
        ctx.stroke();
      }
      ctx.restore();
    }
    if (boss) {
      // halo
      ctx.strokeStyle = rgba(glow, 0.4);
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.ellipse(0, -104 + float, 26, 7, Math.sin(t) * 0.1, 0, TAU);
      ctx.stroke();
    }
  }

  updateParticles(dt) {
    for (let i = this.particles.length - 1; i >= 0; i--) {
      const p = this.particles[i];
      p.life -= dt;
      if (p.life <= 0) { this.particles.splice(i, 1); continue; }
      p.vy += (p.gravity || 0) * dt;
      p.x += p.vx * dt;
      p.y += p.vy * dt;
    }
  }

  drawParticles(ctx) {
    for (const p of this.particles) {
      const a = clamp(p.life / (p.max || 1), 0, 1);
      ctx.globalAlpha = a;
      ctx.fillStyle = p.color;
      ctx.beginPath();
      ctx.arc(p.x, p.y, p.size, 0, TAU);
      ctx.fill();
    }
    ctx.globalAlpha = 1;
  }

  drawFloats(dt, ctx) {
    for (let i = this.floats.length - 1; i >= 0; i--) {
      const f = this.floats[i];
      f.life -= dt;
      if (f.life <= 0) { this.floats.splice(i, 1); continue; }
      f.y += f.vy * dt;
      f.vy *= 0.95;
      const a = clamp(f.life / (f.max || 1), 0, 1);
      ctx.globalAlpha = a;
      ctx.font = `700 ${f.size}px ui-monospace, monospace`;
      ctx.textAlign = 'center';
      ctx.lineWidth = 3;
      ctx.strokeStyle = 'rgba(0,0,0,0.8)';
      ctx.strokeText(f.text, f.x, f.y);
      ctx.fillStyle = f.color;
      ctx.fillText(f.text, f.x, f.y);
      ctx.globalAlpha = 1;
    }
    ctx.textAlign = 'left';
  }
}

import {
  ORES, ORE_ORDER, LAYERS, ZONES, STIM_MAX,
  fmt, fmtRate, costLabel, canAfford, pickPower, pickaxeCost, crewCost,
  drillCost, drillRate, weaponCost, armorCost, stimCost, playerStats,
  nodeRichness, layerMaxHp, strikeYield, overloadGain, playerAttackInterval,
} from './data.js';

const $ = (id) => document.getElementById(id);
const setText = (el, text) => { if (el && el.textContent !== text) el.textContent = text; };

export class UI {
  constructor(game) {
    this.game = game;
    this.toastId = 0;
    this.lastLogId = -1;
    this.savedTimer = 0;
    this.refs = {};
    this.buildResources();
    this.buildLayers();
    this.buildCards();
    this.buildDrills();
    this.buildZones();
    this.cacheRefs();
    this.bind();
    this.render();
  }

  get s() { return this.game.state; }

  buildResources() {
    const wrap = $('resources');
    this.resEls = {};
    const specs = [
      { key: 'caps', name: 'CAPS', color: '#e9c46a', cls: 'caps' },
      ...ORE_ORDER.map((key) => ({ key, name: ORES[key].name.toUpperCase(), color: ORES[key].color })),
      { key: 'shards', name: 'SHARDS', color: '#b98aff', cls: 'shards' },
    ];
    for (const spec of specs) {
      const chip = document.createElement('div');
      chip.className = `res-chip ${spec.cls || ''}`;
      chip.title = spec.name;
      const dot = document.createElement('span');
      dot.className = 'dot';
      dot.style.setProperty('--c', spec.color);
      const meta = document.createElement('span');
      meta.className = 'res-meta';
      const name = document.createElement('span');
      name.className = 'res-name';
      name.textContent = spec.name;
      const val = document.createElement('span');
      val.className = 'res-val';
      val.textContent = '0';
      const per = document.createElement('span');
      per.className = 'res-per';
      meta.append(name, val);
      chip.append(dot, meta, per);
      wrap.append(chip);
      this.resEls[spec.key] = { chip, val, per };
    }
  }

  buildLayers() {
    const wrap = $('layerStrip');
    this.layerEls = LAYERS.map((layer, i) => {
      const btn = document.createElement('button');
      btn.type = 'button';
      btn.className = 'layer-btn';
      btn.dataset.action = 'layer';
      btn.dataset.index = String(i);
      btn.innerHTML = `
        <span class="l-name"><i class="l-ore" style="--c:${layer.glow}"></i><span>${layer.short}</span></span>
        <span class="l-req"></span>`;
      wrap.append(btn);
      return { btn, req: btn.querySelector('.l-req') };
    });
  }

  buildCards() {
    const fmtCard = (id, icon, title) => `
      <button class="card" type="button" data-action="${id}" id="card-${id}">
        <span class="card-icon">${icon}</span>
        <span class="card-body">
          <span class="card-top"><span class="card-title">${title}</span><span class="card-lvl" data-lvl>LV.1</span></span>
          <span class="card-desc" data-desc></span>
          <span class="card-cost" data-cost></span>
        </span>
        <span class="card-cta" data-cta>UPGRADE</span>
      </button>`;

    $('toolCards').innerHTML = fmtCard('pickaxe', '⚒', 'PICKAXE') + fmtCard('crew', '☗', 'SURVIVOR CREW');
    $('gearCards').innerHTML = fmtCard('weapon', '⚔', 'PIPE AXE') + fmtCard('armor', '⛨', 'RAD PLATE') + fmtCard('stim', '✚', 'STIM KIT');

    this.cardEls = {};
    for (const id of ['pickaxe', 'crew', 'weapon', 'armor', 'stim']) {
      const card = $(`card-${id}`);
      this.cardEls[id] = {
        card,
        lvl: card.querySelector('[data-lvl]'),
        desc: card.querySelector('[data-desc]'),
        cost: card.querySelector('[data-cost]'),
        cta: card.querySelector('[data-cta]'),
      };
    }
  }

  buildDrills() {
    const wrap = $('drillList');
    this.drillEls = LAYERS.map((layer, i) => {
      const btn = document.createElement('button');
      btn.type = 'button';
      btn.className = 'drill-row';
      btn.dataset.action = 'drill';
      btn.dataset.index = String(i);
      btn.innerHTML = `
        <span class="drill-dot" style="--c:${layer.glow}"></span>
        <span class="drill-name">${ORES[layer.ore].name} Drill<small></small></span>
        <span class="drill-buy"><span data-cost></span><b>BUY</b></span>`;
      wrap.append(btn);
      return { btn, name: btn.querySelector('.drill-name'), sub: btn.querySelector('.drill-name small'), cost: btn.querySelector('[data-cost]'), buy: btn.querySelector('.drill-buy') };
    });
  }

  buildZones() {
    const wrap = $('zoneList');
    this.zoneEls = ZONES.map((zone, i) => {
      const btn = document.createElement('button');
      btn.type = 'button';
      btn.className = 'zone-row';
      btn.dataset.action = 'zone';
      btn.dataset.index = String(i);
      btn.innerHTML = `
        <span>
          <span class="z-name"><i class="z-dot"></i>${zone.name}</span>
          <span class="z-sub"></span>
        </span>
        <span class="z-status"></span>`;
      wrap.append(btn);
      return { btn, name: btn.querySelector('.z-name'), sub: btn.querySelector('.z-sub'), status: btn.querySelector('.z-status') };
    });
  }

  cacheRefs() {
    const r = this.refs;
    r.layerBadge = $('layerBadge');
    r.veinLabel = $('veinLabel');
    r.richnessLabel = $('richnessLabel');
    r.veinHpText = $('veinHpText');
    r.veinBar = $('veinBar');
    r.strikeSub = $('strikeSub');
    r.pickPower = $('pickPower');
    r.autoYield = $('autoYield');
    r.depthText = $('depthText');
    r.objectiveText = $('objectiveText');
    r.sceneTip = $('sceneTip');
    r.drillRateTotal = $('drillRateTotal');
    r.crewBadge = $('crewBadge');
    r.coreDesc = $('coreDesc');
    r.overloadBtn = $('overloadBtn');
    r.enemyName = $('enemyName');
    r.wavePill = $('wavePill');
    r.enemyBar = $('enemyBar');
    r.playerBar = $('playerBar');
    r.playerHpText = $('playerHpText');
    r.deathBanner = $('deathBanner');
    r.autoBtn = $('autoBtn');
    r.autoLabel = $('autoLabel');
    r.attackBtn = $('attackBtn');
    r.atkStat = $('atkStat');
    r.defStat = $('defStat');
    r.killStat = $('killStat');
    r.zoneBadge = $('zoneBadge');
    r.zoneProgress = $('zoneProgress');
    r.tickerText = $('tickerText');
    r.ticker = $('ticker');
    r.playStats = $('playStats');
    r.saveState = $('saveState');
    r.soundBtn = $('soundBtn');
  }

  bind() {
    document.addEventListener('click', (e) => {
      const target = e.target.closest('[data-action]');
      if (target) {
        const action = target.dataset.action;
        const index = Number(target.dataset.index || 0);
        this.dispatch(action, index);
        return;
      }
      const tab = e.target.closest('[data-tab]');
      if (tab) {
        this.setTab(tab.dataset.tab);
        return;
      }
      if (e.target.closest('#soundBtn')) {
        this.game.toggleSound();
        return;
      }
      if (e.target.closest('#resetBtn')) {
        this.game.confirmReset();
      }
    });

    document.addEventListener('keydown', (e) => {
      if (e.repeat) return;
      if (e.code === 'Space') {
        e.preventDefault();
        if (document.getElementById('app').dataset.tab === 'mine' || window.innerWidth > 980) this.game.strikeMine();
      } else if (e.key === 'f' || e.key === 'F') {
        if (document.getElementById('app').dataset.tab === 'fight' || window.innerWidth > 980) this.game.attack();
      }
    });

    window.addEventListener('resize', () => {
      this.game.mineRenderer?.resize();
      this.game.combatRenderer?.resize();
    });
  }

  dispatch(action, index) {
    const g = this.game;
    switch (action) {
      case 'strike': g.strikeMine(); break;
      case 'attack': g.attack(); break;
      case 'auto': g.toggleAuto(); break;
      case 'pickaxe': g.buyPickaxe(); break;
      case 'crew': g.buyCrew(); break;
      case 'weapon': g.buyWeapon(); break;
      case 'armor': g.buyArmor(); break;
      case 'stim': g.buyStim(); break;
      case 'drill': g.buyDrill(index); break;
      case 'layer': g.selectLayer(index); break;
      case 'zone': g.selectZone(index); break;
      case 'overload': g.confirmOverload(); break;
      default: break;
    }
  }

  setTab(tab) {
    const app = $('app');
    app.dataset.tab = tab;
    document.querySelectorAll('.tab').forEach((el) => el.classList.toggle('active', el.dataset.tab === tab));
    // let the browser apply display before measuring canvas rects
    requestAnimationFrame(() => {
      this.game.mineRenderer?.resize();
      this.game.combatRenderer?.resize();
    });
  }

  render() {
    if (!this.s) return;
    this.renderResources();
    this.renderMine();
    this.renderForge();
    this.renderFight();
    this.renderLog();
    this.renderFooter();
  }

  renderResources() {
    const s = this.s;
    const showShards = s.shards > 0;
    for (const key of ORE_ORDER) {
      const ref = this.resEls[key];
      const unlocked = LAYERS.findIndex((l) => l.ore === key) < s.layersUnlocked;
      const visible = unlocked || (s.ores[key] || 0) > 0;
      ref.chip.style.display = visible ? '' : 'none';
      ref.chip.classList.toggle('locked', !unlocked);
      setText(ref.val, fmt(s.ores[key] || 0));
      const layerIndex = LAYERS.findIndex((l) => l.ore === key);
      const rate = layerIndex >= 0 ? (s.drills[layerIndex] || 0) * drillRate(s, layerIndex) : 0;
      setText(ref.per, rate > 0 ? `+${fmtRate(rate)}` : '');
      ref.chip.title = `${ORES[key].name}${rate > 0 ? ` · ${fmtRate(rate)}` : ''}`;
    }
    const caps = this.resEls.caps;
    setText(caps.val, fmt(s.caps));
    caps.chip.title = `Salvage caps · earned in combat. ${fmt(s.stats.totalCaps || 0)} lifetime.`;
    const shards = this.resEls.shards;
    shards.chip.style.display = showShards ? '' : 'none';
    setText(shards.val, fmt(s.shards));
    shards.chip.title = `Core shards · +${Math.round(s.shards * 10)}% ore, +${Math.round(s.shards * 8)}% damage`;
  }

  renderMine() {
    const s = this.s;
    const r = this.refs;
    const layer = LAYERS[s.layer] || LAYERS[0];
    const node = s.nodes[s.layer] || 0;
    const maxHp = layerMaxHp(s, s.layer);
    const hp = Math.min(maxHp, s.veinHp[s.layer] ?? maxHp);
    setText(r.layerBadge, `${layer.short} // ${layer.depth}M`);
    setText(r.veinLabel, `VEIN ${String(node + 1).padStart(2, '0')}`);
    setText(r.richnessLabel, `RICH ×${nodeRichness(node).toFixed(2)}`);
    setText(r.veinHpText, `${Math.ceil(hp)} / ${maxHp}`);
    r.veinBar.style.width = `${Math.max(0, Math.min(100, (hp / maxHp) * 100))}%`;
    setText(r.strikeSub, `+${fmt(strikeYield(s, s.layer), 1)} ${ORES[layer.ore].name.toUpperCase()} PER HIT`);
    setText(r.pickPower, fmt(pickPower(s), 1));
    const totalRate = LAYERS.reduce((sum, _, i) => sum + (s.drills[i] || 0) * drillRate(s, i), 0);
    setText(r.autoYield, fmtRate(totalRate));
    setText(r.depthText, `${layer.name.toUpperCase()} // ${layer.depth}M`);
    r.sceneTip.classList.toggle('hidden', (s.stats.clicks || 0) > 3);
    setText(r.objectiveText, this.objectiveText());

    this.layerEls.forEach(({ btn, req }, i) => {
      const l = LAYERS[i];
      btn.classList.toggle('active', i === s.layer);
      const unlocked = i < s.layersUnlocked;
      btn.classList.toggle('locked', !unlocked);
      const unlock = l.unlock;
      let ready = false;
      if (!unlocked && unlock) {
        ready = s.pickaxe >= unlock.pickaxe && canAffordOre(s, unlock.ore);
      }
      btn.classList.toggle('ready', ready);
      if (unlocked) {
        const rate = (s.drills[i] || 0) * drillRate(s, i);
        setText(req, `${l.baseYield}/hit${rate > 0 ? ` · +${fmtRate(rate)}` : ''}`);
      } else if (ready) {
        setText(req, `UNLOCK · ${costLabel(unlock.ore)}`);
      } else {
        setText(req, `PK.${unlock.pickaxe} · ${costLabel(unlock.ore)}`);
      }
    });
  }

  renderForge() {
    const s = this.s;
    const r = this.refs;
    const p = playerStats(s);

    // pickaxe
    const pc = pickaxeCost(s.pickaxe);
    const pcAff = canAfford(s, pc);
    const pick = this.cardEls.pickaxe;
    pick.lvl.textContent = `LV.${s.pickaxe}`;
    pick.desc.innerHTML = `Power <b>${fmt(pickPower(s), 1)}</b> → <b>${fmt(2 + 2.3 * s.pickaxe, 1)}</b> · cracks all ore veins`;
    pick.cost.textContent = costLabel(pc);
    pick.card.classList.toggle('affordable', pcAff);
    pick.cta.textContent = 'UPGRADE';

    // crew
    const cc = crewCost(s.crew);
    const ccAff = canAfford(s, cc);
    const crew = this.cardEls.crew;
    crew.lvl.textContent = `LV.${s.crew}`;
    crew.desc.innerHTML = `Ore yield <b>+${s.crew * 8}%</b> → <b>+${(s.crew + 1) * 8}%</b> · survivors work the rigs`;
    crew.cost.textContent = costLabel(cc);
    crew.card.classList.toggle('affordable', ccAff);
    crew.cta.textContent = 'RECRUIT';
    setText(r.crewBadge, `CREW ${s.crew}`);
    setText(r.drillRateTotal, `${fmtRate(LAYERS.reduce((sum, _, i) => sum + (s.drills[i] || 0) * drillRate(s, i), 0))}`);

    // gear
    const wc = weaponCost(s.gear.weapon);
    const wAff = canAfford(s, wc);
    const weapon = this.cardEls.weapon;
    weapon.lvl.textContent = `LV.${s.gear.weapon}`;
    weapon.desc.innerHTML = `Damage <b>${fmt(p.attack, 1)}</b> → <b>${fmt(p.attack + 4 * (1 + (s.shards * 0.08)), 1)}</b> per strike · 12% crit`;
    weapon.cost.textContent = costLabel(wc);
    weapon.card.classList.toggle('affordable', wAff);
    weapon.cta.textContent = 'FORGE';

    const ac = armorCost(s.gear.armor);
    const aAff = canAfford(s, ac);
    const armor = this.cardEls.armor;
    armor.lvl.textContent = `LV.${s.gear.armor}`;
    armor.desc.innerHTML = `HP <b>${fmt(p.maxHp)}</b> → <b>${fmt(p.maxHp + 30)}</b> · ${Math.round(p.defense * 100)}% damage resist`;
    armor.cost.textContent = costLabel(ac);
    armor.card.classList.toggle('affordable', aAff);
    armor.cta.textContent = 'FORGE';

    const stimMax = s.gear.stim >= STIM_MAX;
    const stim = this.cardEls.stim;
    stim.lvl.textContent = `LV.${s.gear.stim}`;
    if (stimMax) {
      stim.desc.innerHTML = `Heals <b>${p.healPerKill}</b> HP per kill · knockout ${p.deathMs / 1000}s`;
      stim.cost.textContent = 'Max tier reached';
      stim.card.classList.remove('affordable');
      stim.card.classList.add('maxed');
      stim.cta.textContent = 'MAX';
    } else {
      const sc = stimCost(s.gear.stim);
      const sAff = canAfford(s, sc);
      stim.desc.innerHTML = `Heals <b>${p.healPerKill}</b> → <b>${8 + 5 * (s.gear.stim + 1)}</b> HP per kill · faster reboot`;
      stim.cost.textContent = costLabel(sc);
      stim.card.classList.toggle('affordable', sAff);
      stim.card.classList.remove('maxed');
      stim.cta.textContent = 'BUILD';
    }

    // drills
    this.drillEls.forEach(({ btn, name, sub, cost, buy }, i) => {
      const unlocked = i < s.layersUnlocked;
      const l = LAYERS[i];
      const count = s.drills[i] || 0;
      btn.classList.toggle('locked', !unlocked);
      name.firstChild.textContent = `${ORES[l.ore].name} Drill`;
      if (!unlocked) {
        sub.textContent = 'Layer not yet opened';
        cost.textContent = 'LOCKED';
        buy.classList.remove('show');
        btn.classList.remove('affordable');
      } else {
        const per = drillRate(s, i);
        sub.textContent = `×${count} · ${fmtRate(per)} each · ${fmtRate(per * count)} total`;
        const dc = drillCost(i, count);
        cost.textContent = costLabel(dc);
        btn.classList.toggle('affordable', canAfford(s, dc));
      }
      cost.closest('.drill-buy').querySelector('b').textContent = 'BUY';
    });

    // core
    const gain = overloadGain(s);
    r.overloadBtn.disabled = s.combat.primeKills < 1;
    if (s.combat.primeKills < 1) {
      r.coreDesc.textContent = 'Defeat Warden Prime in The Black Vault to charge the core. Overloading resets your run for permanent shards.';
      r.coreDesc.classList.remove('ready');
    } else {
      r.coreDesc.textContent = `Core charged by ${s.combat.primeKills} Prime kill${s.combat.primeKills > 1 ? 's' : ''}. Overload yields ${gain} core shard${gain > 1 ? 's' : ''} and resets ore, rigs, and territory.`;
      r.coreDesc.classList.add('ready');
    }
  }

  renderFight() {
    const s = this.s;
    const c = s.combat;
    const r = this.refs;
    const zone = ZONES[c.zone] || ZONES[0];
    const stats = playerStats(s);
    const enemy = c.enemy;
    const dead = c.deadUntil > Date.now();

    setText(r.zoneBadge, zone.name.toUpperCase());
    setText(r.zoneProgress, `${c.unlocked} / ${ZONES.length} SECURED`);
    setText(r.wavePill, enemy ? `${enemy.boss ? 'BOSS · ' : ''}WAVE ${c.waves[c.zone] || 1}` : `WAVE ${c.waves[c.zone] || 1}`);
    r.wavePill.classList.toggle('boss', !!enemy?.boss);
    if (enemy) {
      setText(r.enemyName, enemy.name.toUpperCase());
      r.enemyName.style.color = enemy.boss ? '#ffb15c' : '';
      const pct = Math.max(0, Math.min(100, (enemy.hp / Math.max(1, enemy.maxHp)) * 100));
      r.enemyBar.style.width = `${pct}%`;
      r.enemyBar.style.filter = enemy.boss ? 'saturate(1.3)' : '';
    } else {
      setText(r.enemyName, 'SCANNING…');
      r.enemyBar.style.width = '0%';
    }
    const hpPct = Math.max(0, Math.min(100, (c.hp / stats.maxHp) * 100));
    r.playerBar.style.width = `${hpPct}%`;
    setText(r.playerHpText, `${fmt(Math.max(0, c.hp))} / ${fmt(stats.maxHp)}`);
    setText(r.atkStat, fmt(stats.attack, 1));
    setText(r.defStat, `${Math.round(stats.defense * 100)}%`);
    setText(r.killStat, fmt(s.stats.kills || 0));
    r.deathBanner.hidden = !dead;
    if (dead) setText(r.deathBanner, `FLATLINED — REBOOTING ${Math.max(1, Math.ceil((c.deadUntil - Date.now()) / 1000))}s`);
    r.autoBtn.classList.toggle('on', !!c.auto);
    r.autoBtn.setAttribute('aria-pressed', String(!!c.auto));
    setText(r.autoLabel, c.auto ? 'AUTO: ON' : 'AUTO: OFF');
    const cooling = Date.now() < (c.nextPlayerAttack || 0);
    r.attackBtn.classList.toggle('cooling', cooling && !dead);

    this.zoneEls.forEach(({ btn, name, sub, status }, i) => {
      const z = ZONES[i];
      const unlocked = i < c.unlocked;
      btn.classList.toggle('locked', !unlocked);
      btn.classList.toggle('active', i === c.zone);
      name.querySelector('.z-dot').style.background = unlocked ? z.accent : '#4a4f43';
      name.querySelector('.z-dot').style.boxShadow = unlocked ? `0 0 6px ${z.accent}` : 'none';
      if (unlocked) {
        btn.classList.remove('ready');
        sub.textContent = `${z.unlock ? `${z.baseHp} HP` : 'STARTING GROUND'} · WAVE ${c.waves[i]} · ~${fmt(z.caps)} caps/kill`;
        if (i === c.zone) {
          status.innerHTML = `<b>ACTIVE</b>${z.enemies[0]}`;
          status.classList.add('active-tag');
        } else {
          status.innerHTML = `<b>TRAVEL</b>WAVE ${c.waves[i]}`;
          status.classList.remove('active-tag');
        }
      } else {
        const req = z.unlock;
        const ready = canAfford(s, { caps: req.caps, ...req.ore });
        btn.classList.toggle('ready', ready);
        status.classList.remove('active-tag');
        sub.textContent = `${z.baseDmg} DMG · ${fmt(z.caps)} caps/kill · ${ORES[z.ore].name}`;
        status.innerHTML = ready ? `<b>UNLOCK</b>${fmt(req.caps)} CAPS` : `<b>LOCKED</b>${fmt(req.caps)} CAPS`;
      }
    });
  }

  renderLog() {
    const log = this.game.logs;
    if (!log.length) return;
    const latest = log[log.length - 1];
    if (latest.id === this.lastLogId) return;
    this.lastLogId = latest.id;
    setText(this.refs.tickerText, latest.text);
    this.refs.tickerText.className = latest.type || '';
  }

  renderFooter() {
    const s = this.s;
    setText(this.refs.playStats, `${fmt(s.stats.totalMined)} ore mined · ${fmt(s.stats.kills)} kills · ${s.stats.detonations} overloads`);
    setText(this.refs.saveState, this.savedTimer > 0 ? 'SAVED ✓' : 'AUTOSAVE ON');
    if (this.savedTimer > 0) this.savedTimer -= 0.5;
  }

  objectiveText() {
    const s = this.s;
    if ((s.stats.clicks || 0) < 5) return `Strike the ore vein — ${Math.min(5, s.stats.clicks || 0)}/5 swings.`;
    if ((s.drills[0] || 0) === 0) return 'Build a scrap drill in the FORGE so ore flows while you fight.';
    if (s.pickaxe < 3) return `Upgrade the pickaxe to Lv.3 — currently Lv.${s.pickaxe}.`;
    if (s.layersUnlocked < 2) return 'Open Rust Flats from the shaft map.';
    if ((s.stats.kills || 0) < 5) return `Win ${Math.min(5, s.stats.kills || 0)}/5 fights in the wasteland.`;
    if (s.combat.unlocked < 2) return 'Unlock Highway Camp and push deeper into the ruins.';
    if (s.crew < 1) return 'Recruit a survivor crew to boost every ore source.';
    if (s.layersUnlocked < LAYERS.length) return `Descend: open ${LAYERS[s.layersUnlocked].name}.`;
    if (s.combat.unlocked < ZONES.length) return `Secure ${ZONES[s.combat.unlocked].name} at the edge of the map.`;
    if (s.combat.primeKills < 1) return 'Reach wave 10 in The Black Vault and kill Warden Prime.';
    return 'The core is charged. Overload the reactor for permanent shards.';
  }

  toast(text, type = '') {
    const wrap = $('toasts');
    const el = document.createElement('div');
    el.className = `toast ${type}`;
    el.textContent = text;
    wrap.append(el);
    while (wrap.children.length > 4) wrap.removeChild(wrap.firstChild);
    setTimeout(() => el.remove(), 3100);
  }

  log(text, type = '') {
    this.game.logs.push({ id: ++this.toastId + 1000, text, type, at: Date.now() });
    if (this.game.logs.length > 30) this.game.logs.shift();
    this.renderLog();
  }

  setSaveFlash() {
    this.savedTimer = 2;
  }

  updateSoundButton() {
    const btn = this.refs.soundBtn;
    if (!btn) return;
    btn.classList.toggle('off', !this.s.sound);
    btn.textContent = this.s.sound ? '♪' : '♪';
    btn.setAttribute('aria-pressed', String(!!this.s.sound));
    btn.title = this.s.sound ? 'Mute sound' : 'Enable sound';
  }

  openModal({ eyebrow = 'SYSTEM', title, body, actions = [] }) {
    const modal = $('modal');
    $('modalEyebrow').textContent = eyebrow;
    $('modalTitle').textContent = title;
    const bodyEl = $('modalBody');
    bodyEl.innerHTML = body;
    const actionsEl = $('modalActions');
    actionsEl.innerHTML = '';
    for (const action of actions) {
      const btn = document.createElement('button');
      btn.type = 'button';
      btn.className = `btn ${action.kind || ''}`;
      btn.textContent = action.label;
      btn.addEventListener('click', () => {
        if (action.keepOpen !== true) this.closeModal();
        action.onClick?.();
      }, { once: true });
      actionsEl.append(btn);
    }
    modal.hidden = false;
    modal.querySelector('.modal-card').focus?.();
  }

  closeModal() {
    const modal = $('modal');
    modal.hidden = true;
  }
}

function canAffordOre(state, oreCost) {
  return Object.entries(oreCost).every(([k, v]) => (state.ores[k] || 0) >= v);
}

import {
  LAYERS, ZONES, ORES, ORE_ORDER, STIM_MAX,
  fmt, costLabel, canAfford, spend, makeEnemy, playerStats,
  playerAttackInterval, layerMaxHp, strikeYield, pickPower,
  drillRate, overloadGain, zoneReward,
} from './data.js';
import { loadState, persist, wipeSave, offlineReport, resetProgress, formatGainList } from './state.js';
import { GameAudio } from './audio.js';
import { MineRenderer, CombatRenderer } from './render.js';
import { UI } from './ui.js';

const $ = (id) => document.getElementById(id);

class Game {
  constructor() {
    const loaded = loadState();
    this.state = loaded.state;
    this.fresh = loaded.fresh;
    this.logs = [];
    this.audio = new GameAudio(this.state.sound);
    this.nextSpawn = 0;
    this.lastStrike = 0;
    this.lastTick = performance.now();
    this.lastUI = 0;
    this.lastSave = performance.now();

    const offline = offlineReport(this.state);
    this.setupEnemy(performance.now());

    this.mineRenderer = new MineRenderer($('mineCanvas'), this);
    this.combatRenderer = new CombatRenderer($('combatCanvas'), this);
    this.ui = new UI(this);
    this.ui.updateSoundButton();

    this.seedLog();
    if (offline) this.showOffline(offline);
    else if (this.fresh) {
      this.log('Rig online. Strike the vein and rebuild. The wastes are listening.', 'good');
    } else {
      this.log('Rig restored from last session.', 'good');
    }

    this.bindGlobal();
    this.tick = this.tick.bind(this);
    setInterval(() => this.tick(performance.now()), 100);
    setInterval(() => this.ui.render(), 150);
    this.saveNow();
  }

  setupEnemy(now) {
    const c = this.state.combat;
    if (!c.enemy || !c.enemy.hp || c.enemy.hp <= 0) {
      const wave = c.waves[c.zone] || 1;
      c.enemy = makeEnemy(c.zone, wave);
    }
    c.enemy.nextAttack = now + c.enemy.interval * 0.9;
    c.nextPlayerAttack = 0;
    if (c.hp <= 0) {
      const stats = playerStats(this.state);
      c.hp = stats.maxHp;
      c.deadUntil = 0;
    }
  }

  seedLog() {}

  bindGlobal() {
    document.getElementById('modal').addEventListener('click', (e) => {
      if (e.target.id === 'modal') this.ui.closeModal();
    });
    document.addEventListener('keydown', (e) => {
      if (e.key === 'Escape') this.ui.closeModal();
    });
    window.addEventListener('pagehide', () => this.saveNow());
    document.addEventListener('visibilitychange', () => {
      if (document.hidden) this.saveNow();
      else this.lastTick = performance.now();
    });
  }

  tick(now) {
    const dt = Math.min(1.5, Math.max(0, (now - this.lastTick) / 1000));
    this.lastTick = now;
    this.passiveGain(dt);
    this.tickCombat(now, dt);
    if (now - this.lastUI > 150) {
      this.ui.render();
      this.lastUI = now;
    }
    if (now - this.lastSave > 5000) {
      this.saveNow();
      this.lastSave = now;
    }
  }

  passiveGain(dt) {
    const s = this.state;
    for (let i = 0; i < LAYERS.length; i++) {
      const count = s.drills[i] || 0;
      if (!count) continue;
      const ore = LAYERS[i].ore;
      const amount = count * drillRate(s, i) * dt;
      s.ores[ore] += amount;
      s.stats.totalMined += amount;
    }
  }

  /* ── mining ──────────────────────────────────────────────── */
  strikeMine() {
    const now = performance.now();
    if (now - this.lastStrike < 45) return;
    this.lastStrike = now;
    const s = this.state;
    const i = s.layer;
    const layer = LAYERS[i];
    const yieldAmt = strikeYield(s, i);
    const crit = Math.random() < 0.07;
    const gained = yieldAmt * (crit ? 3 : 1);
    s.ores[layer.ore] += gained;
    s.stats.totalMined += gained;
    s.stats.clicks = (s.stats.clicks || 0) + 1;

    const dmg = pickPower(s);
    const maxHp = layerMaxHp(s, i);
    s.veinHp[i] = (s.veinHp[i] ?? maxHp) - dmg;
    let broke = false;
    if (s.veinHp[i] <= 0) {
      broke = true;
      const bonus = yieldAmt * 10;
      s.ores[layer.ore] += bonus;
      s.stats.totalMined += bonus;
      s.nodes[i] = (s.nodes[i] || 0) + 1;
      s.veinHp[i] = layerMaxHp(s, i);
      this.mineRenderer.veinBreak();
      this.audio.shatter();
      this.log(`Vein shattered. Richness ×${(1 + 0.04 * s.nodes[i]).toFixed(2)} · +${fmt(bonus)} ${ORES[layer.ore].name}.`, 'good');
    } else {
      this.audio[crit ? 'crit' : 'strike']();
    }
    this.mineRenderer.strike();
    this.mineRenderer.floatOre(Math.round(gained), layer.ore, crit);
    if (broke) {
      this.mineRenderer.floatOre(Math.round(yieldAmt * 10), layer.ore, true);
      this.ui.toast(`VEIN SHATTERED · +${fmt(Math.round(yieldAmt * 10))} ${ORES[layer.ore].name}`, 'good');
    } else if (crit) {
      this.ui.toast(`CRITICAL SEAM · +${fmt(Math.round(gained))} ${ORES[layer.ore].name}`, 'good');
    }
    if ((s.stats.clicks || 0) === 1) {
      this.log('First swing. Keep the pick moving — the vein gives more the deeper you go.', 'good');
    }
    this.ui.render();
  }

  selectLayer(index) {
    const s = this.state;
    if (index < 0 || index >= LAYERS.length) return;
    if (index < s.layersUnlocked) {
      if (s.layer !== index) {
        s.layer = index;
        this.log(`Descended to ${LAYERS[index].name}.`, '');
        this.ui.render();
      }
      return;
    }
    if (index !== s.layersUnlocked) {
      this.ui.toast('Open the earlier shafts first.', 'bad');
      this.audio.error();
      return;
    }
    const layer = LAYERS[index];
    const req = layer.unlock;
    if (s.pickaxe < req.pickaxe) {
      this.ui.toast(`Requires pickaxe Lv.${req.pickaxe}. You have Lv.${s.pickaxe}.`, 'bad');
      this.audio.error();
      return;
    }
    if (!canAfford(s, req.ore)) {
      this.ui.toast(`Need ${costLabel(req.ore)} to break through.`, 'bad');
      this.audio.error();
      return;
    }
    spend(s, req.ore);
    s.layersUnlocked = index + 1;
    s.layer = index;
    this.audio.buy();
    this.ui.toast(`NEW SHAFT · ${layer.name}`, 'good');
    this.log(`${layer.name} opened at ${layer.depth}m. ${layer.blurb}`, 'good');
    this.ui.render();
    this.saveNow();
  }

  buyPickaxe() {
    const s = this.state;
    const cost = pickaxeCostValue(s);
    if (!canAfford(s, cost)) return this.deny(cost);
    spend(s, cost);
    s.pickaxe += 1;
    this.audio.buy();
    this.log(`Pickaxe upgraded to Lv.${s.pickaxe}. Vein damage ${fmt(pickPower(s), 1)}.`, 'good');
    if (s.pickaxe === 3) this.ui.toast('Pickaxe Lv.3 — Rust Flats can be opened.', 'good');
    this.ui.render();
  }

  buyCrew() {
    const s = this.state;
    const cost = crewCostValue(s);
    if (!canAfford(s, cost)) return this.deny(cost);
    spend(s, cost);
    s.crew += 1;
    this.audio.buy();
    this.ui.toast(`Survivor ${s.crew} joined · ore yield +${s.crew * 8}%`, 'good');
    this.log(`Crew expanded to ${s.crew}. Every ore source is ${s.crew * 8}% richer.`, 'good');
    this.ui.render();
  }

  buyDrill(index) {
    const s = this.state;
    if (index < 0 || index >= s.layersUnlocked) {
      this.ui.toast('That shaft is not open yet.', 'bad');
      this.audio.error();
      return;
    }
    const cost = drillCostValue(index, s.drills[index] || 0);
    if (!canAfford(s, cost)) return this.deny(cost);
    spend(s, cost);
    s.drills[index] = (s.drills[index] || 0) + 1;
    this.audio.buy();
    const layer = LAYERS[index];
    this.log(`Drill rig ${s.drills[index]} online in ${layer.name} · +${fmt(drillRate(s, index), 2)} ${ORES[layer.ore].name}/s.`, 'good');
    this.ui.render();
  }

  buyWeapon() {
    const s = this.state;
    const cost = weaponCostValue(s);
    if (!canAfford(s, cost)) return this.deny(cost);
    spend(s, cost);
    s.combat.gear.weapon += 1;
    this.audio.buy();
    const stats = playerStats(s);
    this.log(`Pipe axe reforged. Attack ${fmt(stats.attack, 1)}.`, 'good');
    this.ui.render();
  }

  buyArmor() {
    const s = this.state;
    const cost = armorCostValue(s);
    if (!canAfford(s, cost)) return this.deny(cost);
    const oldMax = playerStats(s).maxHp;
    spend(s, cost);
    s.combat.gear.armor += 1;
    const stats = playerStats(s);
    s.combat.hp = Math.min(stats.maxHp, s.combat.hp + (stats.maxHp - oldMax));
    this.audio.buy();
    this.log(`Rad plate fitted. HP ${fmt(stats.maxHp)} · ${Math.round(stats.defense * 100)}% resist.`, 'good');
    this.ui.render();
  }

  buyStim() {
    const s = this.state;
    if (s.combat.gear.stim >= STIM_MAX) {
      this.ui.toast('Stim kit is already at max tier.', 'bad');
      return;
    }
    const cost = stimCostValue(s);
    if (!canAfford(s, cost)) return this.deny(cost);
    spend(s, cost);
    s.combat.gear.stim += 1;
    this.audio.buy();
    const stats = playerStats(s);
    this.ui.toast(`Stim kit built · +${stats.healPerKill} HP per kill`, 'good');
    this.log(`Stim kit rebuilt. Heals ${stats.healPerKill} HP after each kill; reboot time ${stats.deathMs / 1000}s.`, 'good');
    this.ui.render();
  }

  deny(cost) {
    this.audio.error();
    this.ui.toast(`Not enough salvage — need ${costLabel(cost)}.`, 'bad');
  }

  /* ── combat ──────────────────────────────────────────────── */
  tickCombat(now, dt) {
    const s = this.state;
    const c = s.combat;
    const stats = playerStats(s);

    if (c.deadUntil > 0) {
      if (now >= c.deadUntil) {
        c.deadUntil = 0;
        c.hp = stats.maxHp;
        c.enemy = makeEnemy(c.zone, c.waves[c.zone]);
        c.enemy.nextAttack = now + c.enemy.interval;
        c.nextPlayerAttack = 0;
        this.nextSpawn = 0;
        this.combatRenderer.respawn();
        this.log('Reboot complete. Back on your feet.', '');
      }
      return;
    }

    if (!c.enemy) {
      if (now >= this.nextSpawn) {
        c.enemy = makeEnemy(c.zone, c.waves[c.zone]);
        c.enemy.nextAttack = now + c.enemy.interval * 0.9;
      } else {
        return;
      }
    }

    const enemy = c.enemy;
    c.hp = Math.min(stats.maxHp, c.hp + stats.maxHp * 0.007 * dt);

    if (c.auto && now >= (c.nextPlayerAttack || 0)) this.attack(now, true);

    if (c.enemy && now >= (c.enemy.nextAttack || 0) && c.deadUntil === 0) {
      const live = c.enemy;
      live.nextAttack = now + live.interval;
      this.combatRenderer.enemyAttack();
      this.audio.hurt();
      const dmg = live.dmg * (1 - stats.defense);
      c.hp -= dmg;
      this.combatRenderer.hurtNumber(dmg);
      this.combatRenderer.playerHit();
      if (c.hp <= 0) this.playerDied(now, stats);
    }
  }

  attack(now = performance.now(), auto = false) {
    const s = this.state;
    const c = s.combat;
    if (c.deadUntil > 0 || !c.enemy) return;
    if (now < (c.nextPlayerAttack || 0)) return;
    c.nextPlayerAttack = now + playerAttackInterval();
    const stats = playerStats(s);
    const crit = Math.random() < 0.12;
    const dmg = stats.attack * (0.9 + Math.random() * 0.2) * (crit ? 1.9 : 1);
    c.enemy.hp -= dmg;
    this.combatRenderer.playerAttack();
    this.combatRenderer.enemyHit();
    this.combatRenderer.damageNumber(dmg, crit);
    if (crit) this.audio.crit(); else this.audio.hit();

    if (c.enemy.hp <= 0) this.killEnemy(now, stats);
    this.ui.render();
  }

  killEnemy(now, stats) {
    const s = this.state;
    const c = s.combat;
    const enemy = c.enemy;
    const zone = ZONES[c.zone];
    const caps = enemy.caps;
    const oreAmt = enemy.oreAmt;
    s.caps += caps;
    s.ores[enemy.ore] = (s.ores[enemy.ore] || 0) + oreAmt;
    s.stats.totalCaps = (s.stats.totalCaps || 0) + caps;
    s.stats.totalMined += oreAmt;
    s.stats.kills = (s.stats.kills || 0) + 1;
    s.combat.hp = Math.min(stats.maxHp, s.combat.hp + stats.healPerKill);
    c.waves[c.zone] = (c.waves[c.zone] || 1) + 1;

    this.combatRenderer.enemyKilled(c.zone, enemy.boss);
    this.audio.kill();
    if (enemy.boss) {
      this.ui.toast(`${enemy.name} DOWN · +${fmt(caps)} caps`, 'good');
      this.log(`${enemy.name} fell. +${fmt(caps)} caps · +${fmt(oreAmt)} ${ORES[enemy.ore].name}.`, 'good');
      this.audio.overload();
      if (c.zone === ZONES.length - 1) {
        c.primeKills += 1;
        this.log('Warden Prime is dead. The reactor core is exposed. You can overload it in the FORGE.', 'lore');
        this.ui.toast('CORE CHARGED · OVERLOAD AVAILABLE IN FORGE', 'lore');
      }
    } else {
      this.log(`${enemy.name} down · +${fmt(caps)} caps · +${fmt(oreAmt)} ${ORES[enemy.ore].name}.`, '');
    }
    if (c.waves[c.zone] % 10 === 1 && c.waves[c.zone] > 1) {
      this.log(`Wave ${c.waves[c.zone]} in ${zone.name}. Something bigger is coming.`, 'alert');
    }
    c.enemy = null;
    this.nextSpawn = now + 700;
    this.ui.render();
    this.saveNow();
  }

  playerDied(now, stats) {
    const s = this.state;
    const c = s.combat;
    c.hp = 0;
    c.deadUntil = now + stats.deathMs;
    c.enemy = null;
    this.nextSpawn = now + stats.deathMs + 300;
    this.combatRenderer.playerDied();
    this.audio.death();
    this.log(`Knocked out in ${ZONES[c.zone].name}. Reboot in ${(stats.deathMs / 1000).toFixed(1)}s.`, 'alert');
    this.ui.toast('FLATLINED · AUTO-REBOOT IN ' + Math.ceil(stats.deathMs / 1000) + 's', 'bad');
    this.ui.render();
  }

  toggleAuto() {
    const c = this.state.combat;
    c.auto = !c.auto;
    this.audio.tone({ freq: c.auto ? 520 : 280, dur: 0.08, type: 'triangle', vol: 0.16 });
    this.log(`Auto-attack ${c.auto ? 'engaged' : 'disengaged'}.`, '');
    this.ui.render();
    this.saveNow();
  }

  selectZone(index) {
    const s = this.state;
    const c = s.combat;
    if (index < 0 || index >= ZONES.length) return;
    if (index < c.unlocked) {
      if (index === c.zone) return;
      c.zone = index;
      c.enemy = makeEnemy(index, c.waves[index]);
      c.enemy.nextAttack = performance.now() + c.enemy.interval;
      c.nextPlayerAttack = performance.now() + 300;
      this.combatRenderer.enemyKey = '';
      this.audio.buy();
      this.log(`Travelled to ${ZONES[index].name}. Wave ${c.waves[index]}.`, '');
      this.ui.render();
      return;
    }
    if (index !== c.unlocked) {
      this.ui.toast('Secure the earlier sectors first.', 'bad');
      this.audio.error();
      return;
    }
    const zone = ZONES[index];
    const req = zone.unlock;
    const cost = { caps: req.caps, ...req.ore };
    if (!canAfford(s, cost)) {
      this.ui.toast(`Need ${costLabel(cost)} to secure ${zone.name}.`, 'bad');
      this.audio.error();
      return;
    }
    spend(s, cost);
    c.unlocked = index + 1;
    c.zone = index;
    c.enemy = makeEnemy(index, c.waves[index]);
    c.enemy.nextAttack = performance.now() + c.enemy.interval;
    c.nextPlayerAttack = performance.now() + 300;
    this.combatRenderer.enemyKey = '';
    this.audio.buy();
    this.ui.toast(`TERRITORY SECURED · ${zone.name}`, 'good');
    this.log(`${zone.name} secured. ${zone.enemies.join(', ')} now roam here.`, 'good');
    this.ui.render();
    this.saveNow();
  }

  /* ── meta ────────────────────────────────────────────────── */
  confirmOverload() {
    const s = this.state;
    if (s.combat.primeKills < 1) {
      this.ui.toast('Defeat Warden Prime before overloading the core.', 'bad');
      this.audio.error();
      return;
    }
    const gain = overloadGain(s);
    this.ui.openModal({
      eyebrow: 'REACTOR CONTROL',
      title: 'Overload the core?',
      body: `
        <p>The reactor will detonate. Your ore, drills, pickaxe, crew, gear, caps and territories will be <strong>wiped</strong>.</p>
        <p>You will gain <span class="gain">${gain} core shard${gain > 1 ? 's' : ''}</span> (now ${s.shards}, after ${s.shards + gain}). Each shard gives <strong>+10% ore yield</strong> and <strong>+8% damage</strong>, forever.</p>
        <p>This cannot be undone.</p>`,
      actions: [
        { label: 'CANCEL', kind: '' },
        { label: `DETONATE · +${gain} SHARDS`, kind: 'danger', onClick: () => this.doOverload(gain) },
      ],
    });
  }

  doOverload(gain) {
    const old = this.state;
    const next = resetProgress(old);
    next.shards = old.shards + gain;
    next.stats.detonations = (old.stats.detonations || 0) + 1;
    next.stats.startedAt = old.stats.startedAt;
    next.combat.primeKills = 0;
    this.state = next;
    this.nextSpawn = 0;
    this.setupEnemy(performance.now());
    this.combatRenderer.enemyKey = '';
    this.combatRenderer.respawn();
    this.mineRenderer.lastKey = '';
    this.audio.overload();
    this.ui.toast(`CORE DETONATED · +${gain} SHARDS · ${next.shards} total`, 'lore');
    this.log(`The core detonated. ${gain} shard${gain > 1 ? 's' : ''} recovered · permanent output +${Math.round(next.shards * 10)}%.`, 'lore');
    this.ui.render();
    this.saveNow();
  }

  confirmReset() {
    this.ui.openModal({
      eyebrow: 'EMERGENCY PROTOCOL',
      title: 'Wipe all progress?',
      body: '<p>This erases your save completely: ore, shards, upgrades, territories and stats. The wasteland will not remember you.</p>',
      actions: [
        { label: 'KEEP PLAYING', kind: '' },
        { label: 'WIPE SAVE', kind: 'danger', onClick: () => { wipeSave(); location.reload(); } },
      ],
    });
  }

  toggleSound() {
    this.state.sound = !this.state.sound;
    this.audio.setEnabled(this.state.sound);
    if (this.state.sound) this.audio.buy();
    this.ui.updateSoundButton();
    this.ui.toast(this.state.sound ? 'Sound enabled' : 'Sound muted', '');
    this.saveNow();
  }

  showOffline(report) {
    const rows = ORE_ORDER
      .filter((o) => report.gains[o] > 0)
      .map((o) => `<div class="loot-line"><span>${ORES[o].name}</span><span>+${fmt(report.gains[o], 1)}</span></div>`)
      .join('');
    const secs = report.seconds;
    const time = secs >= 3600 ? `${Math.floor(secs / 3600)}h ${Math.floor((secs % 3600) / 60)}m` : `${Math.max(1, Math.floor(secs / 60))}m`;
    this.ui.openModal({
      eyebrow: 'OFFLINE REPORT',
      title: 'The rigs kept running.',
      body: `
        <p>You were gone for <strong>${time}</strong>. Your drills recovered ore at <strong>50%</strong> efficiency, capped at 8 hours.</p>
        ${rows}
        <p style="margin-top:10px">Combat does not run while the rig is unattended.</p>`,
      actions: [{ label: 'BACK TO WORK', kind: '' }],
    });
    this.log(`Offline rigs recovered ${formatGainList(report.gains)} over ${time}.`, 'good');
  }

  saveNow() {
    const ok = persist(this.state);
    if (ok) this.ui?.setSaveFlash();
    return ok;
  }
}

/* Resolve cost helpers from the data module with concise calls. */
import * as D from './data.js';
const pickaxeCostValue = (s) => D.pickaxeCost(s.pickaxe);
const crewCostValue = (s) => D.crewCost(s.crew);
const drillCostValue = (i, count) => D.drillCost(i, count);
const weaponCostValue = (s) => D.weaponCost(s.combat.gear.weapon);
const armorCostValue = (s) => D.armorCost(s.combat.gear.armor);
const stimCostValue = (s) => D.stimCost(s.combat.gear.stim);

window.game = new Game();

input.newString:
export const ORE_ORDER = ['scrap', 'iron', 'copper', 'titanium', 'uranium', 'singularity'];

/* Outfits are permanent survivor gear. Each level is bought with caps (money) + ore. */
export const OUTFITS = [
  {
    id: 'rebreather', name: 'Glowcap Rebreather', slot: 'HEAD', icon: '☣',
    max: 15,
    blurb: 'A scavenged filter rig. Sharpens the eye and the mind.',
    effect: (lvl) => `Crit +${(lvl * 1.5).toFixed(1)}% · XP +${lvl * 4}%`,
    cost: (lvl) => ({ caps: Math.ceil(80 * Math.pow(1.5, lvl)), iron: Math.ceil(10 * Math.pow(1.4, lvl)) }),
  },
  {
    id: 'duster', name: 'Slagwalker Duster', slot: 'COAT', icon: '⛨',
    max: 15,
    blurb: 'Waxed canvas and welded plate. Built to take a beating.',
    effect: (lvl) => `Max HP +${(lvl * 2.5).toFixed(1)}% · Resist +${(lvl * 0.6).toFixed(1)}%`,
    cost: (lvl) => ({ caps: Math.ceil(100 * Math.pow(1.5, lvl)), scrap: Math.ceil(120 * Math.pow(1.4, lvl)) }),
  },
  {
    id: 'charm', name: 'Warden Charm', slot: 'CHARM', icon: '✦',
    max: 15,
    blurb: 'A dead warden\'s token. The wastes pay tribute to it.',
    effect: (lvl) => `Caps +${lvl * 3}% · Ore +${(lvl * 1.5).toFixed(1)}%`,
    cost: (lvl) => ({ caps: Math.ceil(180 * Math.pow(1.5, lvl)), iron: Math.ceil(25 * Math.pow(1.4, lvl)) }),
  },
];

export const OUTFIT_MAP = Object.fromEntries(OUTFITS.map((o) => [o.id, o]));

export function outfitLevel(state, id) {
  return Math.max(0, Math.floor(Number(state.outfits?.[id]) || 0));
}

export function outfitCost(outfit, level) {
  return outfit.cost(level);
}

export function outfitOreMult(state) {
  return 1 + outfitLevel(state, 'charm') * 0.015;
}

export function outfitCapsMult(state) {
  return 1 + outfitLevel(state, 'charm') * 0.03;
}

export function outfitXpMult(state) {
  return 1 + outfitLevel(state, 'rebreather') * 0.04;
}

export function xpNeeded(level) {
  return Math.floor(60 * Math.pow(Math.max(1, level), 1.55));
}

