    attrBefore = await page.locator('.attr-row').first().innerText();
    await page.locator('.attr-plus').first().click();
    await page.waitForTimeout(400);
    attrAfter = await page.locator('.attr-row').first().innerText();
  }
  const afterSpend = await page.evaluate(() => {
    const a = window.__ASHFALL__;
