  await page.reload({ waitUntil: 'networkidle' });
  await page.waitForTimeout(1200);
  const reloaded = await page.evaluate(() => {
    const a = window.__ASHFALL__;
    return { level: a.state.level, points: a.state.points, perks: { ...a.state.perks }, outfits: { ...a.state.outfits }, attributes: { ...a.state.attributes } };
  });

