    title, hasCanvas, state, afterMine, fightInfo, levelInfo,
    plusCount, attrBefore, attrAfter, afterSpend, perkModalVisible, perkBtns, afterPerk,
    outfitBefore, outfitAfter, saved: saved ? saved.length : 0, reloaded,
    errors, consoleMessages: consoleMessages.slice(-20),
  }, null, 2));

  await browser.close();
})().catch((err) => {
  console.error('SCRIPT FAILED', err);
  process.exit(1);
});

