const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright-core');
(async () => {
  const browser = await chromium.launch({ executablePath: '/usr/bin/chromium', headless: true, args: ['--no-sandbox', '--disable-gpu'] });
  const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
  const logs = [];
  page.on('console', (m) => logs.push(`${m.type()}: ${m.text()}`));
  page.on('pageerror', (e) => logs.push('PAGEERROR: ' + e.message + '\n' + e.stack));
  page.on('requestfailed', (r) => logs.push('REQFAIL: ' + r.url() + ' ' + r.failure()?.errorText));
  await page.goto('http://localhost:3002', { waitUntil: 'networkidle' });
  await page.waitForTimeout(2000);
  console.log('logs:\n' + logs.join('\n'));
  console.log('game type:', await page.evaluate(() => typeof window.game));
  console.log('body:', (await page.locator('body').innerText()).slice(0, 600));
  await page.screenshot({ path: 'screenshots/debug.png' });
  await browser.close();
})();

