const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright-core');

async function tab(page, name) {
  const btn = page.locator(`.tab[data-tab="${name}"]`);
  if (await btn.isVisible().catch(() => false)) await btn.click();
  else await page.evaluate((n) => window.game.ui.setTab(n), name);
  await page.waitForTimeout(500);
}

(async () => {
  const browser = await chromium.launch({
    executablePath: '/usr/bin/chromium',
    headless: true,
    args: ['--no-sandbox', '--disable-gpu'],
  });
  const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
  const errors = [];
  page.on('console', (msg) => { if (msg.type() === 'error') errors.push(msg.text()); });
  page.on('pageerror', (err) => errors.push('PAGEERROR: ' + err.message));

  await page.goto('http://localhost:3002', { waitUntil: 'networkidle' });
  await page.waitForTimeout(1200);

  const state0 = await page.evaluate(() => {
    const a = window.game;
    return { level: a.state.level, caps: a.state.caps, xp: a.state.xp, points: a.state.points, ore: { ...a.state.ores } };
  });
  await page.screenshot({ path: 'screenshots/desktop-mine.png' });

  const box = await page.locator('#mineCanvas').boundingBox();
  if (box) {
    for (let i = 0; i < 8; i++) {
      await page.mouse.click(box.x + box.width * 0.6, box.y + box.height * 0.55);
      await page.waitForTimeout(130);
    }
  }
  await page.waitForTimeout(300);
  const afterMine = await page.evaluate(() => {
    const a = window.game;
    return { ore: { ...a.state.ores }, clicks: a.state.stats.clicks, totalMined: a.state.stats.totalMined, level: a.state.level, xp: a.state.xp };
  });

  await tab(page, 'fight');
  await page.waitForTimeout(1800);
  await page.screenshot({ path: 'screenshots/desktop-fight.png' });
  const fightInfo = await page.evaluate(() => {
    const a = window.game;
    return { zone: a.state.combat.zone, enemy: a.state.combat.enemy?.name, enemyHp: a.state.combat.enemy?.hp, hp: a.state.combat.hp, waves: a.state.combat.waves };
  });

  // force XP to test level-up
  await page.evaluate(() => window.game.gainXp(700));
  await page.waitForTimeout(600);
  const levelInfo = await page.evaluate(() => {
    const a = window.game;
    return { level: a.state.level, xp: a.state.xp, points: a.state.points, perkPoints: a.state.perkPoints };
  });

  await tab(page, 'forge');
  await page.screenshot({ path: 'screenshots/desktop-forge.png' });

  const plusCount = await page.locator('.attr-plus').count();
  let attrBefore = null, attrAfter = null;
  if (plusCount) {
    attrBefore = (await page.locator('.attr-row').first().innerText()).replace(/\n/g, ' | ');
    await page.locator('.attr-plus').first().click();
    await page.waitForTimeout(400);
    attrAfter = (await page.locator('.attr-row').first().innerText()).replace(/\n/g, ' | ');
  }
  const afterSpend = await page.evaluate(() => {
    const a = window.game;
    return { points: a.state.points, attributes: { ...a.state.attributes } };
  });

  await page.locator('#perkBtn').click();
  await page.waitForTimeout(400);
  const perkModalVisible = await page.locator('#modal').isVisible().catch(() => false);
  const modalTitle = perkModalVisible ? await page.locator('#modalTitle').innerText() : '';
  await page.screenshot({ path: 'screenshots/desktop-perks.png' });
  const perkBtns = await page.locator('.modal-actions button').count();
  if (perkModalVisible && perkBtns > 1) {
    await page.locator('.modal-actions button').last().click();
    await page.waitForTimeout(400);
  }
  const afterPerk = await page.evaluate(() => {
    const a = window.game;
    return { perks: { ...a.state.perks }, perkPoints: a.state.perkPoints };
  });

  // Outfit purchase
  await page.evaluate(() => { window.game.state.caps += 5000; window.game.ui.render(); });
  await page.waitForTimeout(300);
  const outfitBtn = page.locator('.outfit-card').first();
  await outfitBtn.scrollIntoViewIfNeeded();
  const outfitBefore = (await outfitBtn.innerText()).replace(/\n/g, ' | ');
  await outfitBtn.click();
  await page.waitForTimeout(500);
  const outfitAfter = await page.evaluate(() => {
    const a = window.game;
    return { outfits: { ...a.state.outfits }, caps: a.state.caps };
  });
  await page.screenshot({ path: 'screenshots/desktop-outfits.png' });

  // Buy a drill + pickaxe from forge visible state
  const beforeBuy = await page.evaluate(() => ({ caps: window.game.state.caps, pickaxe: window.game.state.pickaxe, drills: [...window.game.state.drills] }));
  await page.evaluate(() => { window.game.state.caps += 1000; window.game.state.ores.scrap += 1000; window.game.ui.render(); });
  await page.locator('#strikeBtn').click().catch(() => {});
  const pickaxeBtn = page.locator('#toolCards .card').first();
  await pickaxeBtn.click().catch(() => {});
  await page.waitForTimeout(400);
  const afterBuy = await page.evaluate(() => ({ caps: window.game.state.caps, pickaxe: window.game.state.pickaxe, drills: [...window.game.state.drills] }));

  // Save / reload persistence
  await page.evaluate(() => window.game.saveNow());
  await page.waitForTimeout(300);
  const saved = await page.evaluate(() => localStorage.getItem('ashfall.save.v1'));
  await page.reload({ waitUntil: 'networkidle' });
  await page.waitForTimeout(1400);
  const reloaded = await page.evaluate(() => {
    const a = window.game;
    return { level: a.state.level, points: a.state.points, perks: { ...a.state.perks }, outfits: { ...a.state.outfits }, attributes: { ...a.state.attributes }, pickaxe: a.state.pickaxe, caps: a.state.caps };
  });

  // Mobile
  await page.setViewportSize({ width: 390, height: 844 });
  await page.waitForTimeout(700);
  await tab(page, 'fight');
  await page.screenshot({ path: 'screenshots/mobile-fight.png' });
  await tab(page, 'mine');
  await page.screenshot({ path: 'screenshots/mobile-mine.png' });
  await tab(page, 'forge');
  await page.screenshot({ path: 'screenshots/mobile-forge.png' });

  const overflow = await page.evaluate(() => ({
    scrollW: document.documentElement.scrollWidth,
    clientW: document.documentElement.clientWidth,
    scrollH: document.documentElement.scrollHeight,
    clientH: document.documentElement.clientHeight,
  }));

  console.log(JSON.stringify({
    state0, afterMine, fightInfo, levelInfo,
    plusCount, attrBefore, attrAfter, afterSpend, perkModalVisible, modalTitle, perkBtns, afterPerk,
    outfitBefore, outfitAfter, beforeBuy, afterBuy,
    savedLen: saved ? saved.length : 0, reloaded, overflow, errors,
  }, null, 2));

  await browser.close();
})().catch((err) => {
  console.error('SCRIPT FAILED', err);
  process.exit(1);
});

