const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright-core');
(async () => {
  const browser = await chromium.launch({ executablePath: '/usr/bin/chromium', headless: true, args: ['--no-sandbox', '--disable-gpu'] });
  const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
  const errors = [];
  page.on('pageerror', (e) => errors.push(e.message));
  await page.goto('http://localhost:3002', { waitUntil: 'networkidle' });
  await page.waitForTimeout(800);

  // Zone persistence
  const zoneBefore = await page.evaluate(() => {
    const g = window.game;
    g.state.combat.unlocked = 3;
    g.state.combat.zone = 2;
    g.saveNow();
    return { zone: g.state.combat.zone, unlocked: g.state.combat.unlocked };
  });
  await page.reload({ waitUntil: 'networkidle' });
  await page.waitForTimeout(900);
  const zoneAfter = await page.evaluate(() => ({ zone: window.game.state.combat.zone, unlocked: window.game.state.combat.unlocked }));

  // Offline gains
  const offline = await page.evaluate(async () => {
    const { offlineReport } = await import('./js/state.js');
    const g = window.game;
    g.state.drills[0] = 4;
    g.state.lastSeen = Date.now() - 3600 * 1000;
    const before = g.state.ores.scrap;
    const report = offlineReport(g.state);
    return { report: report ? { seconds: report.seconds, gains: report.gains } : null, delta: g.state.ores.scrap - before };
  });

  // Prestige
  const prestige = await page.evaluate(() => {
    const g = window.game;
    const s = g.state;
    s.combat.primeKills = 1;
    s.shards = 2;
    s.level = 9;
    s.xp = 42;
    s.points = 5;
    s.perkPoints = 2;
    s.attributes = { str: 3, vit: 2, agi: 1, luk: 4 };
    s.perks = { berserker: 2, prospector: 1 };
    s.outfits = { rebreather: 3, duster: 2, charm: 1 };
    s.ores.scrap = 999;
    s.caps = 888;
    s.pickaxe = 7;
    s.drills[0] = 5;
    s.combat.gear = { weapon: 5, armor: 4, stim: 3 };
    s.combat.unlocked = 4;
    s.combat.waves[3] = 7;
    g.saveNow();
    return { before: { level: s.level, shards: s.shards, xp: s.xp } };
  });
  await page.locator('.tab[data-tab="forge"]').click().catch(() => {});
  await page.waitForTimeout(300);
  await page.evaluate(() => document.querySelector('#overloadBtn').click());
  await page.waitForTimeout(400);
  const modalVisible = await page.locator('#modal').isVisible();
  // click DETONATE (last action)
  await page.locator('.modal-actions button').last().click();
  await page.waitForTimeout(700);
  const prestigeAfter = await page.evaluate(() => {
    const s = window.game.state;
    return {
      shards: s.shards, level: s.level, xp: s.xp, points: s.points, perkPoints: s.perkPoints,
      attributes: { ...s.attributes }, perks: { ...s.perks }, outfits: { ...s.outfits },
      ores: { ...s.ores }, caps: s.caps, pickaxe: s.pickaxe, drills: [...s.drills],
      gear: { ...s.combat.gear }, unlocked: s.combat.unlocked, primeKills: s.combat.primeKills,
      hp: s.combat.hp,
    };
  });

  // save string size and final state
  await page.evaluate(() => window.game.saveNow());
  const save = await page.evaluate(() => localStorage.getItem('ashfall.save.v1'));
  console.log(JSON.stringify({ zoneBefore, zoneAfter, offline, prestige, modalVisible, prestigeAfter, saveLen: save.length, errors }, null, 2));
  await browser.close();
})().catch((e) => { console.error('FAILED', e); process.exit(1); });

