const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright-core');
(async () => {
  const browser = await chromium.launch({ executablePath: '/usr/bin/chromium', headless: true, args: ['--no-sandbox', '--disable-gpu'] });
  const page = await browser.newPage({ viewport: { width: 1440, height: 900 }, deviceScaleFactor: 2 });
  await page.goto('http://localhost:3002', { waitUntil: 'networkidle' });
  await page.waitForTimeout(900);
  await page.evaluate(() => {
    const g = window.game;
    g.state.outfits = { rebreather: 10, duster: 10, charm: 10 };
    g.state.level = 12;
    g.ui.render();
  });
  await page.waitForTimeout(600);
  await page.locator('#mineScene').screenshot({ path: 'screenshots/zoom-mine-outfits.png' });
  await page.evaluate(() => {
    const g = window.game;
    g.state.combat.zone = 3;
    g.state.combat.unlocked = 4;
    g.state.combat.enemy = null;
    g.setupEnemy(performance.now());
    g.state.combat.enemy.hp = 1e9;
    g.state.combat.enemy.maxHp = 1e9;
    g.ui.render();
  });
  await page.waitForTimeout(900);
  await page.locator('#arena').screenshot({ path: 'screenshots/zoom-arena-crater.png' });
  await browser.close();
})();
